// Antwort an die Oberfläche für einen von der KI verfassten Text (Modus A und Modus B): ein ENTWURF, nie eine Bestätigung.
// Die Sensoralarme sind noch nicht mit MQTT verbunden: « alertes » bleibt hier leer; die automatischen
// Kontrollen der Antwort erscheinen in « avertissements » (von der Pflegekraft zu prüfende Punkte).
const r = $input.first().json;
return [
  {
    json: {
      brouillon_id: r.brouillon_id,
      texte: r.texte,
      sources: r.sources ?? [],
      alertes: [],
      retirees: (r.retirees ?? []).map((x) => ({ phrase: x.phrase, source_id: x.source_id, motifs: x.motifs.map((m) => m.libelle), detail: x.detail })),
      avertissements: (r.avertissements ?? []).map((a) => ({ type: a.type, detail: String(a.detail ?? '').slice(0, 200) })),
    },
  },
];

// Sitzungsprüfung – das « Bearer »-Token im Authorization-Header (43 URL-sichere Zeichen) wird gehasht (SHA-256): Nur der Hash steht in der Datenbank.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Sitzungsprüfung – Ergebnis: eine identifizierte Pflegekraft (Sitzung offen, nicht abgelaufen, Konto aktiv) oder nichts.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
